// H14.54 LAB-ONLY identity-assertion verifier: pluggable contract, NOT real authentication.
// Proof: base64url(JSON exact claims).base64url(HMAC-SHA256 test-key).
// Keys and signed assertions are generated by test harness, never checked into source.
import {createHmac,timingSafeEqual} from 'node:crypto';
const fields=['issuer','audience','subject','sessionHandle','sessionId','actionKey','eventId','intent','issuedAt','notBefore','expiresAt'];
const fail=reason=>({ok:false,reason});
const token=x=>typeof x==='string'&&/^[A-Za-z0-9_.:-]{1,128}$/.test(x);
const uuid=x=>typeof x==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(x);
const exact=(x,keys)=>x&&typeof x==='object'&&!Array.isArray(x)&&Object.keys(x).sort().join(',')===keys.slice().sort().join(',');
export function verifyFixtureIdentityAssertion({proof,key,issuer,audience,now}={}){
 if(typeof proof!=='string'||proof.length>2048||!/^[-_A-Za-z0-9]+\.[-_A-Za-z0-9]+$/.test(proof))return fail('invalid_proof');
 if(typeof key!=='string'||key.length<32||!token(issuer)||!token(audience)||!Number.isSafeInteger(now))return fail('verifier_unavailable');
 try{
  const [data,signature]=proof.split('.');
  const bytes=Buffer.from(signature,'base64url');
  if(bytes.length!==32||bytes.toString('base64url')!==signature)return fail('invalid_proof');
  const expected=createHmac('sha256',key).update(data).digest();
  if(!timingSafeEqual(bytes,expected))return fail('untrusted_assertion');
  const raw=Buffer.from(data,'base64url');
  if(raw.length>1200||raw.toString('base64url')!==data)return fail('invalid_proof');
  const claims=JSON.parse(raw.toString('utf8'));
  if(!exact(claims,fields)||claims.issuer!==issuer||claims.audience!==audience||
   !token(claims.subject)||!token(claims.sessionHandle)||!token(claims.sessionId)||
   !token(claims.actionKey)||!uuid(claims.eventId)||!['start','resume','transfer'].includes(claims.intent))
   return fail('invalid_claims');
  const {issuedAt,notBefore,expiresAt}=claims;
  if(![issuedAt,notBefore,expiresAt].every(Number.isSafeInteger)||
    issuedAt>now+30||notBefore>now||expiresAt<=now||issuedAt>notBefore||
    expiresAt-issuedAt>300||now-issuedAt>300)
   return fail('proof_expired_or_not_yet_valid');
  return {ok:true,claims:Object.freeze({...claims})};
 }catch{return fail('invalid_proof');}
}
